package com.procurement.approvalstage.service;
import com.procurement.approvalrule.entity.ApprovalRule;import com.procurement.approvalrule.repository.ApprovalRuleRepository;import com.procurement.approvalstage.dto.request.*;import com.procurement.approvalstage.dto.response.*;import com.procurement.approvalstage.entity.*;import com.procurement.approvalstage.exception.*;import com.procurement.approvalstage.mapper.*;import com.procurement.approvalstage.repository.*;import com.procurement.approvalstage.specification.*;import com.procurement.common.exception.*;import com.procurement.common.response.*;import com.procurement.role.entity.Role;import com.procurement.role.repository.RoleRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ApprovalStageServiceImpl implements ApprovalStageService{private final ApprovalStageRepository repo;private final ApprovalRuleRepository rules;private final RoleRepository roles;private final ApprovalStageMapper mapper;public ApprovalStageServiceImpl(ApprovalStageRepository r,ApprovalRuleRepository a,RoleRepository o,ApprovalStageMapper m){repo=r;rules=a;roles=o;mapper=m;}private ApprovalStage find(Long id){return repo.findById(id).orElseThrow(()->new ApprovalStageNotFoundException(id));}private ApprovalRule rule(Long id){return rules.findById(id).orElseThrow(()->new ResourceNotFoundException("Approval rule not found: "+id));}private Role role(Long id){return roles.findById(id).orElseThrow(()->new ResourceNotFoundException("Role not found: "+id));}private void unique(ApprovalStageRequest r,Long ignore){var list=repo.findAll((x,q,b)->b.and(b.equal(x.get("approvalRule").get("id"),r.approvalRuleId()),b.equal(x.get("sequence"),r.sequence())));if(list.stream().anyMatch(x->!x.getId().equals(ignore)))throw new ConflictException("Sequence already exists for this approval rule");}@Transactional public ApprovalStageResponse create(ApprovalStageRequest r){unique(r,null);return mapper.toResponse(repo.save(mapper.toEntity(r,rule(r.approvalRuleId()),role(r.approverRoleId()))));}@Transactional(readOnly=true)public PageResponse<ApprovalStageResponse> search(Long a,Long o,Boolean active,Pageable p){Page<ApprovalStageResponse>x=repo.findAll(ApprovalStageSpecification.search(a,o,active),p).map(mapper::toResponse);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public ApprovalStageResponse getById(Long id){return mapper.toResponse(find(id));}@Transactional public ApprovalStageResponse update(Long id,ApprovalStageRequest r){unique(r,id);var e=find(id);mapper.update(e,r,rule(r.approvalRuleId()),role(r.approverRoleId()));return mapper.toResponse(repo.save(e));}@Transactional public void delete(Long id){repo.delete(find(id));}}
